function grade(mark) {
  if (mark >= 75) return "A";
  if (mark >= 65) return "B";
  if (mark >= 50) return "C";
  return "U";
}

js-arrays-top-learners.code:
function topNames(learners, n) {
  return [...learners].sort((a, b) => b.xp - a.xp).slice(0, n).map((l) => l.name);
}

ts-cart-total.code:
type CartLine = { product: string; qty: number };

function cartTotal(cart: CartLine[], prices: Record<string, number>): number {
  let total = 0;
  for (const line of cart) {
    const price = prices[line.product];
    if (price === undefined) throw new Error(`Unknown product: ${line.product}`);
    total += price * line.qty;
  }
  return total;
}
